package com.yitaihuang.ticketrush.order;

import java.time.Duration;
import java.time.Instant;

import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import jakarta.persistence.Version;

import org.hibernate.annotations.JdbcTypeCode;
import org.hibernate.type.SqlTypes;

import com.yitaihuang.ticketrush.common.ApiException;

@Entity
@Table(name = "orders")
public class Order {

	/** Generated by the reservation service, so the client knows it before the row exists. */
	@Id
	private String id;

	private long eventId;

	private String userId;

	private int quantity;

	private int amountCents;

	@Enumerated(EnumType.STRING)
	@JdbcTypeCode(SqlTypes.VARCHAR)
	private OrderStatus status;

	private String idempotencyKey;

	private Instant expiresAt;

	private Instant createdAt;

	private Instant updatedAt;

	/**
	 * Optimistic lock. "Pay" and "expire" can race on the same order; whichever
	 * commits second fails instead of silently overwriting the first.
	 */
	@Version
	private Long version;

	protected Order() {
	}

	private Order(OrderRequested request, OrderStatus status, Instant expiresAt, Instant now) {
		this.id = request.orderId();
		this.eventId = request.eventId();
		this.userId = request.userId();
		this.quantity = request.quantity();
		this.amountCents = request.amountCents();
		this.idempotencyKey = request.idempotencyKey();
		this.status = status;
		this.expiresAt = expiresAt;
		this.createdAt = now;
		this.updatedAt = now;
	}

	static Order pendingPayment(OrderRequested request, Instant now, Duration paymentWindow) {
		return new Order(request, OrderStatus.PENDING_PAYMENT, now.plus(paymentWindow), now);
	}

	static Order rejected(OrderRequested request, Instant now) {
		return new Order(request, OrderStatus.REJECTED, now, now);
	}

	void pay(Instant now) {
		requirePendingPayment();
		if (!now.isBefore(expiresAt)) {
			throw ApiException.conflict("ORDER_EXPIRED", "The payment window for this order has closed");
		}
		transitionTo(OrderStatus.PAID, now);
	}

	void cancel(Instant now) {
		requirePendingPayment();
		transitionTo(OrderStatus.CANCELLED, now);
	}

	void expire(Instant now) {
		requirePendingPayment();
		transitionTo(OrderStatus.EXPIRED, now);
	}

	boolean isOwnedBy(String userId) {
		return this.userId.equals(userId);
	}

	/** Whether this order is what an idempotent retry with this user, event and quantity asked for. */
	public boolean isSameRequestAs(long eventId, String userId, int quantity) {
		return this.eventId == eventId && this.userId.equals(userId) && this.quantity == quantity;
	}

	/** Whether {@code request} is the message this order was created from (a redelivery, not a conflict). */
	boolean isSameRequest(OrderRequested request) {
		return id.equals(request.orderId()) && eventId == request.eventId() && userId.equals(request.userId())
				&& quantity == request.quantity() && amountCents == request.amountCents()
				&& idempotencyKey.equals(request.idempotencyKey());
	}

	private void requirePendingPayment() {
		if (status != OrderStatus.PENDING_PAYMENT) {
			throw ApiException.conflict("INVALID_ORDER_STATE", "Order is " + status);
		}
	}

	private void transitionTo(OrderStatus next, Instant now) {
		this.status = next;
		this.updatedAt = now;
	}

	public String getId() {
		return id;
	}

	public long getEventId() {
		return eventId;
	}

	public String getUserId() {
		return userId;
	}

	public int getQuantity() {
		return quantity;
	}

	public int getAmountCents() {
		return amountCents;
	}

	public OrderStatus getStatus() {
		return status;
	}

	public Instant getExpiresAt() {
		return expiresAt;
	}

	public Instant getCreatedAt() {
		return createdAt;
	}

	public String getIdempotencyKey() {
		return idempotencyKey;
	}

}
